import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);

  // ============ DÉMARRER CAMÉRA ============
  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: 'user', width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: false
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError("Impossible d'accéder à la caméra");
      }
    };

    startCamera();

    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    };
  }, []);

  // ============ BOUCLE AUTO ============
  useEffect(() => {
    if (!autoMode) {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
      return;
    }

    captureIntervalRef.current = setInterval(async () => {
      if (!videoRef.current || isProcessingRef.current) return;

      try {
        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth || 1280;
        canvas.height = videoRef.current.videoHeight || 720;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0);

        const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);

        console.log("Frontend: Image capturée et envoyée au backend");

        isProcessingRef.current = true;
        setFrameCount(prev => prev + 1);

        const response = await attendanceAPI.recognize({ image_base64: imageBase64 });
        console.log("Frontend: Réponse brute reçue du backend", response);

        const data = response?.data;

        if (data.backend_received) {
          console.log("Backend: Image bien reçue");
        }
        if (data.pipeline_processed) {
          console.log("Pipeline_service: Résultat généré");
        }
        if (data.success !== undefined) {
          console.log("Backend → Frontend: Résultat transmis");
        }

        if (data.success && data.student) {
          setResult({
            success: true,
            name: data.student,
            email: data.email || 'N/A',
            confidence: (data.confidence * 100).toFixed(1),
            attendanceId: data.attendance_id,
            timestamp: new Date().toLocaleTimeString(),
            message: `${data.student} reconnu`
          });
          setLastDetection(new Date().toLocaleTimeString());
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 3000);
        } else if (data.message) {
          setError(data.message);
        }
      } catch (err) {
        console.warn("Erreur requête:", err.message);
      } finally {
        isProcessingRef.current = false;
      }
    }, 1000); // capture toutes les secondes pour debug
    return () => {
      if (captureIntervalRef.current) clearInterval(captureIntervalRef.current);
    };
  }, [autoMode]);

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>Reconnaissance Faciale (Debug)</h1>
      <video ref={videoRef} autoPlay playsInline muted style={styles.video} />
      {error && <div style={styles.errorBox}>{error}</div>}
      {result && (
        <div style={styles.resultBox}>
          <h3>{result.message}</h3>
          <p>Nom: {result.name}</p>
          <p>Email: {result.email}</p>
          <p>Confiance: {result.confidence}%</p>
          <p>ID Présence: {result.attendanceId}</p>
          <p>Heure: {result.timestamp}</p>
        </div>
      )}
    </div>
  );
};

const styles = {
  container: { padding: '20px', fontFamily: 'Arial, sans-serif' },
  title: { fontSize: '1.5rem', marginBottom: '20px' },
  video: { width: '640px', height: '360px', background: '#000' },
  errorBox: { marginTop: '15px', padding: '10px', background: '#fee2e2', color: '#b91c1c' },
  resultBox: { marginTop: '20px', padding: '15px', background: '#f9fafb', borderRadius: '6px' }
};

export default CameraRecognition;
